# -*- coding: utf-8 -*-
"""MANAPRINT — TUAMOTU · 5 boules · maquette Canva de Maeva (27/11/2026, « tuamotu_canva_12_A4 »).
Reprise TELLE QUELLE : 12 cartons / feuille A4 PORTRAIT (3 x 4), traits de coupe en pointillés.
Chaque carton : TUAMOTU, la carte des atolls avec leurs noms, les oiseaux, les cocotiers et le
soleil couchant (dessins Canva posés en pochoir : en couleur, MANAPRINT les repeint avec les
ronds, les chiffres restent noirs), les 5 ronds B · G · I · O · N avec leurs plages, le N°.
RÈGLE (celle de TUAMOTU, inchangée) : un numéro par lettre —
   B 1-15 · I 16-30 · N 31-45 · G 46-60 · O 61-75.   Crieur : 1 à 75.
Chiffres Times 30 pt noirs, comme sur la maquette.
Le tout est réduit pour garder 6 mm de marge d'impression (Konica / Sharp)."""

import io, random
from reportlab.pdfgen import canvas
from reportlab.lib.pagesizes import A4
from reportlab.lib import colors

try:
    from generators import canva_masque as _masque
except Exception:
    import canva_masque as _masque

PAGE_W, PAGE_H = A4
COLS, RANGS = 3, 4
CARTES_PAGE = COLS * RANGS                # 12
CELL_W, CELL_H = 198.4252, 210.4724
NOIR = colors.black
POLICE_NUM = "Times-Roman"
# (centre x, ligne de base, taille) : B 1-15 · G 46-60 · I 16-30 · O 61-75 · N 31-45
CASES = [(30.047, 147.848, 30), (169.512, 146.998, 30), (27.213, 73.014, 30),
         (171.213, 63.943, 30), (94.110, 22.557, 30)]
ORIGINE_Y = 631.4173        # le dessin de la maquette est relevé dans sa case du haut à gauche
_IMGS = [(36.85039, 705.9092, 124.7244, 113.3034), (6.80315, 636.6614, 41.38583, 53.12686),
         (143.1496, 638.9291, 51.02362, 27.37319)]

MARGE_SURE = 6 * 72 / 25.4
ECHELLE = min((PAGE_W - 2 * MARGE_SURE) / PAGE_W, (PAGE_H - 2 * MARGE_SURE) / PAGE_H)
DECAL_X = (PAGE_W - PAGE_W * ECHELLE) / 2.0
DECAL_Y = (PAGE_H - PAGE_H * ECHELLE) / 2.0
_DEJA = set()


def _numeros(rng):
    t = None
    for _ in range(500):
        t = (rng.randint(1, 15), rng.randint(46, 60), rng.randint(16, 30), rng.randint(61, 75),
             rng.randint(31, 45))
        if t not in _DEJA:
            break
    _DEJA.add(t)
    return t


def _txt(c, s, x, y, police, taille, col, centre=False):
    w = c.stringWidth(s, police, taille)
    t = c.beginText(x - w / 2.0 if centre else x, y); t.setFont(police, taille)
    t.setFillColor(col); t.textOut(s)
    c.drawText(t)


def _en_teinte():
    import sys
    for nom in ("app", "__main__"):
        m = sys.modules.get(nom)
        e = getattr(m, "_TEINTE_ETAT", None) if m else None
        if e is not None and getattr(e, "canva", False):
            return True
    return False


def _modele(c):
    if getattr(c, "_tuamotu_modele", False):
        return
    import base64
    d = _DESSIN
    if _en_teinte():          # version couleur : les bulles grises prennent aussi la couleur du billet
        d = d.replace(".12 G", "0 G")
    for k, v in (("{HBI}", "Helvetica-BoldOblique"), ("{HB}", "Helvetica-Bold"), ("{H}", "Helvetica")):
        d = d.replace(k, c._doc.getInternalFontName(v))
    c.beginForm("TUAMOTU_CANVA", 0, 0, CELL_W, CELL_H)
    c._code.append("q\n0 g\n0 G\n1 0 0 1 0 %.4f cm" % -ORIGINE_Y)
    morceaux = d
    for i in range(len(_IMGS)):
        morceaux = morceaux.replace("@IMG%d@" % i, "\x00%d\x00" % i)
    for j, part in enumerate(morceaux.split("\x00")):
        if j % 2 == 1:
            i = int(part); x, y, w, h = _IMGS[i]
            _masque.poser(c, "TUAMOTU_IMG_%d" % i, base64.b64decode(_PNG[i]), x, y, w, h)
        elif part:
            c._code.append(part)
    c._code.append("Q")
    c.endForm()
    c._tuamotu_modele = True


def _billet(c, ox, oy, serie, nums, col):
    _modele(c)
    c.saveState()
    c.translate(ox, oy)
    c.doForm("TUAMOTU_CANVA")
    _txt(c, "N\u00b0 %06d" % serie, 8.503937, 200.8347, "Helvetica", 4.8, colors.Color(.25, .25, .25))
    for (x, y, t), n in zip(CASES, nums):
        _txt(c, str(n), x, y, POLICE_NUM, t, col, centre=True)
    c.restoreState()


def generer_pdf(nb_cartes=None, nb_tickets=None, serie_start=1, theme="", couleur=True,
                nom_evenement="", titre_jeu="", couleur_perso="", date_lieu="",
                telephone="", page_start=1, evenement_id="", style="", motif="", **_ig):
    n_ = nb_cartes if nb_cartes is not None else nb_tickets
    n_ = max(1, int(n_ if n_ else CARTES_PAGE))
    buf = io.BytesIO()
    c = canvas.Canvas(buf, pagesize=(PAGE_W, PAGE_H), pageCompression=1)
    c.setTitle("TUAMOTU · 5 boules")
    rng = random.Random(int(serie_start) * 100003 + 2717)
    _DEJA.clear()
    serie = int(serie_start)
    faits = 0
    try:
        no_page = max(1, int(page_start))
    except Exception:
        no_page = 1
    while faits < n_:
        c.setFillColor(colors.Color(0.5, 0.5, 0.5)); c.setFont("Helvetica", 7)
        c.drawRightString(PAGE_W - DECAL_X, PAGE_H - DECAL_Y / 2.0 - 2.5, "page %d" % no_page)
        entete = "  ·  ".join(t for t in ((nom_evenement or "").strip(), (date_lieu or "").strip()) if t)
        if entete:
            c.setFillColor(NOIR); c.setFont("Helvetica-Bold", 7)
            c.drawCentredString(PAGE_W / 2.0, PAGE_H - DECAL_Y / 2.0 - 2.5, entete)
        c.saveState()
        c.translate(DECAL_X, DECAL_Y); c.scale(ECHELLE, ECHELLE)
        for idx in range(CARTES_PAGE):
            if faits >= n_:
                break
            ox = (idx % COLS) * CELL_W
            oy = (RANGS - 1 - idx // COLS) * CELL_H
            _billet(c, ox, oy, serie, _numeros(rng), NOIR)
            serie += 1
            faits += 1
        c.setStrokeColor(colors.Color(0.5, 0.5, 0.5)); c.setLineWidth(0.3); c.setDash(2, 2)
        for i in range(1, COLS):
            c.line(i * CELL_W, 0, i * CELL_W, RANGS * CELL_H)
        for j in range(1, RANGS):
            c.line(0, j * CELL_H, COLS * CELL_W, j * CELL_H)
        c.restoreState()
        c.showPage()
        no_page += 1
    c.save()
    buf.seek(0)
    return buf


